# Quantitative risk math: is the control worth buying?
awk 'BEGIN{
  sle=50000; aro_before=0.20; aro_after=0.05; cost=8000;
  ale_before=sle*aro_before; ale_after=sle*aro_after;
  printf "ALE before: $%.0f\nALE after:  $%.0f\nSavings:    $%.0f\nCost:       $%.0f\nVerdict:    %s\n", ale_before, ale_after, ale_before-ale_after, cost, (ale_before-ale_after>cost?"BUY":"SKIP");
}'
